const tipos = ['application/pdf', 'image/jpeg', 'image/png', 'image/webp'];
const salida = [];

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const desdeCorreo = Boolean(item.json.messageId || item.json.id && item.json.threadId);
  const remitente = item.json.from?.value?.[0]?.address || null;

  for (const [clave, archivo] of Object.entries(item.binary || {})) {
    if (!tipos.includes(archivo.mimeType)) continue;
    const contenido = await this.helpers.getBinaryDataBuffer(i, clave);
    salida.push({
      json: {
        canal: desdeCorreo ? 'correo' : 'formulario',
        remitente,
        archivo_nombre: archivo.fileName || `${clave}.${archivo.fileExtension || 'pdf'}`,
        archivo_mime: archivo.mimeType,
        archivo_base64: contenido.toString('base64'),
      },
      pairedItem: { item: i },
    });
  }
}

return salida;

const origen = $('Preparar archivos').item.json;
const texto = $json.candidates?.[0]?.content?.parts?.[0]?.text;
if (!texto) throw new Error(`Gemini no devolvió datos para ${origen.archivo_nombre}`);
const f = JSON.parse(texto);

const observaciones = [];
const ruc = String(f.ruc_emisor || '').replace(/\D/g, '');

if (!/^\d{11}$/.test(ruc)) {
  observaciones.push('RUC inválido');
} else {
  if (!['10', '15', '17', '20'].includes(ruc.slice(0, 2))) observaciones.push('Prefijo de RUC no válido');
  const pesos = [5, 4, 3, 2, 7, 6, 5, 4, 3, 2];
  const suma = pesos.reduce((s, p, i) => s + p * Number(ruc[i]), 0);
  let dv = 11 - (suma % 11);
  if (dv === 10) dv = 0;
  if (dv === 11) dv = 1;
  if (dv !== Number(ruc[10])) observaciones.push('Dígito verificador del RUC incorrecto');
}

const serie = String(f.serie || '').toUpperCase();
if (f.tipo === 'factura' && !/^[FE][A-Z0-9]{3}$/.test(serie)) observaciones.push('Serie no corresponde a factura');
if (f.tipo === 'boleta' && !/^[BE][A-Z0-9]{3}$/.test(serie)) observaciones.push('Serie no corresponde a boleta');
const numero = String(f.numero || '').replace(/\D/g, '').replace(/^0+(?=\d)/, '');
if (!numero) observaciones.push('Sin número de comprobante');

if (!/^\d{4}-\d{2}-\d{2}$/.test(f.fecha || '')) observaciones.push('Fecha no legible');
else if (new Date(f.fecha) > new Date()) observaciones.push('Fecha de emisión futura');

const base = Number(f.base_imponible) || 0;
const igv = Number(f.igv) || 0;
const total = Number(f.total) || 0;
if (Math.abs(base + igv - total) > 0.05) observaciones.push('Base más IGV no coincide con el total');
if (Math.abs(base * 0.18 - igv) > 0.05) observaciones.push('IGV distinto al 18%');

const lineas = Array.isArray(f.lineas) ? f.lineas : [];
const sumaLineas = lineas.reduce((s, l) => s + (Number(l.subtotal) || 0), 0);
const lineasCuadran = lineas.length > 0 && Math.abs(sumaLineas - base) <= 0.05;

return {
  json: {
    ...f,
    ruc_emisor: ruc,
    serie,
    numero,
    referencia: `${serie}-${numero.padStart(8, '0')}`,
    moneda: (f.moneda || 'PEN').toUpperCase(),
    base_imponible: base,
    igv,
    total,
    lineas: lineasCuadran ? lineas : [],
    estado: observaciones.length ? 'observada' : 'ok',
    observaciones: observaciones.join('; '),
    canal: origen.canal,
    remitente: origen.remitente,
    archivo_nombre: origen.archivo_nombre,
    archivo_mime: origen.archivo_mime,
  },
};

const cfg = {
  url: $env.ODOO_URL,
  db: $env.ODOO_DB,
  user: $env.ODOO_USER,
  key: $env.ODOO_API_KEY,
  publicUrl: $env.ODOO_PUBLIC_URL || $env.ODOO_URL,
};
const rpc = async (service, method, args) => {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `${cfg.url}/jsonrpc`,
    json: true,
    body: { jsonrpc: '2.0', method: 'call', params: { service, method, args } },
  });
  if (res.error) throw new Error(`Odoo: ${res.error.data?.message || res.error.message}`);
  return res.result;
};
const uid = await rpc('common', 'login', [cfg.db, cfg.user, cfg.key]);
if (!uid) throw new Error('Odoo: usuario o API key incorrectos');
const odoo = (model, method, args, kwargs = {}) =>
  rpc('object', 'execute_kw', [cfg.db, uid, cfg.key, model, method, args, kwargs]);

const f = $json;
const rucValido = /^\d{11}$/.test(f.ruc_emisor);
const nombre = f.razon_social || f.ruc_emisor || 'Proveedor sin identificar';
const existentes = await odoo('res.partner', 'search_read',
  [rucValido ? [['vat', '=', f.ruc_emisor]] : [['name', '=ilike', nombre], ['supplier_rank', '>', 0]]],
  { fields: ['id', 'name'], limit: 1, context: { active_test: false } });

let partnerId;
let proveedorNuevo = false;

if (existentes.length) {
  partnerId = existentes[0].id;
} else {
  const [peru] = await odoo('res.country', 'search_read', [[['code', '=', 'PE']]], { fields: ['id'], limit: 1 });
  partnerId = await odoo('res.partner', 'create', [{
    name: nombre,
    vat: rucValido ? f.ruc_emisor : false,
    is_company: true,
    supplier_rank: 1,
    country_id: peru ? peru.id : false,
  }]);
  proveedorNuevo = true;
}

const duplicadas = await odoo('account.move', 'search_read', [[
  ['move_type', '=', 'in_invoice'],
  ['partner_id', '=', partnerId],
  ['ref', '=', f.referencia],
  ['state', '!=', 'cancel'],
]], { fields: ['id', 'name'], limit: 1 });

return {
  json: {
    ...f,
    partner_id: partnerId,
    proveedor_nuevo: proveedorNuevo,
    duplicada: duplicadas.length > 0,
    factura_existente_id: duplicadas[0]?.id || null,
  },
};

const cfg = {
  url: $env.ODOO_URL,
  db: $env.ODOO_DB,
  user: $env.ODOO_USER,
  key: $env.ODOO_API_KEY,
  publicUrl: $env.ODOO_PUBLIC_URL || $env.ODOO_URL,
};
const rpc = async (service, method, args) => {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `${cfg.url}/jsonrpc`,
    json: true,
    body: { jsonrpc: '2.0', method: 'call', params: { service, method, args } },
  });
  if (res.error) throw new Error(`Odoo: ${res.error.data?.message || res.error.message}`);
  return res.result;
};
const uid = await rpc('common', 'login', [cfg.db, cfg.user, cfg.key]);
if (!uid) throw new Error('Odoo: usuario o API key incorrectos');
const odoo = (model, method, args, kwargs = {}) =>
  rpc('object', 'execute_kw', [cfg.db, uid, cfg.key, model, method, args, kwargs]);

const f = $json;
const archivo = $('Preparar archivos').item.json;

const [impuesto] = await odoo('account.tax', 'search_read', [[
  ['type_tax_use', '=', 'purchase'],
  ['amount_type', '=', 'percent'],
  ['amount', '=', 18],
  ['price_include', '=', false],
]], { fields: ['id'], limit: 1 });
const impuestos = impuesto ? [[6, 0, [impuesto.id]]] : [[6, 0, []]];

const [moneda] = await odoo('res.currency', 'search_read',
  [[['name', '=', f.moneda]]], { fields: ['id'], limit: 1 });

const lineas = f.lineas.length
  ? f.lineas.map((l) => [0, 0, {
      name: l.descripcion,
      quantity: l.cantidad,
      price_unit: l.cantidad ? l.subtotal / l.cantidad : l.precio_unitario,
      tax_ids: impuestos,
    }])
  : [[0, 0, { name: `${f.tipo === 'boleta' ? 'Boleta' : 'Factura'} ${f.referencia}`, quantity: 1, price_unit: f.base_imponible, tax_ids: impuestos }]];

const observaciones = f.observaciones ? [f.observaciones] : [];
if (!moneda) observaciones.push(`Moneda ${f.moneda} no activa en Odoo`);

const valores = {
  move_type: 'in_invoice',
  partner_id: f.partner_id,
  ref: f.referencia,
  invoice_date: /^\d{4}-\d{2}-\d{2}$/.test(f.fecha || '') ? f.fecha : false,
  invoice_line_ids: lineas,
  import_source: 'n8n',
  import_channel: f.canal,
  import_sender: f.remitente || false,
  import_execution: String($execution.id),
};
if (moneda) valores.currency_id = moneda.id;
if (/^\d{4}-\d{2}-\d{2}$/.test(f.fecha_vencimiento || '')) valores.invoice_date_due = f.fecha_vencimiento;
else if (valores.invoice_date) valores.invoice_date_due = valores.invoice_date;

const facturaId = await odoo('account.move', 'create', [valores]);

const [creada] = await odoo('account.move', 'read', [[facturaId]], { fields: ['amount_total'] });
if (Math.abs(creada.amount_total - f.total) > 0.05) {
  observaciones.push(`Total en Odoo ${creada.amount_total.toFixed(2)} distinto al del comprobante ${f.total.toFixed(2)}`);
}

const estado = observaciones.length ? 'observada' : 'ok';
await odoo('account.move', 'write', [[facturaId], {
  validation_state: estado,
  validation_notes: observaciones.join('\n') || false,
}]);

const adjuntoId = await odoo('ir.attachment', 'create', [{
  name: archivo.archivo_nombre,
  datas: archivo.archivo_base64,
  mimetype: archivo.archivo_mime,
  res_model: 'account.move',
  res_id: facturaId,
}]);

await odoo('account.move', 'message_post', [[facturaId]], {
  body: estado === 'ok'
    ? `Comprobante importado y validado. Ejecución ${$execution.id}.`
    : `Comprobante importado con observaciones: ${observaciones.join('; ')}. Ejecución ${$execution.id}.`,
  attachment_ids: [adjuntoId],
  message_type: 'comment',
  subtype_xmlid: 'mail.mt_note',
  context: { no_new_invoice: true },
});
await odoo('account.move', 'write', [[facturaId], { message_main_attachment_id: adjuntoId }]);

return {
  json: {
    factura_id: facturaId,
    referencia: f.referencia,
    proveedor: f.razon_social,
    ruc: f.ruc_emisor,
    proveedor_nuevo: f.proveedor_nuevo,
    moneda: f.moneda,
    total_comprobante: f.total,
    total_odoo: creada.amount_total,
    estado,
    observaciones: observaciones.join('; '),
    canal: f.canal,
    enlace: `${cfg.publicUrl}/odoo/action-account.action_move_in_invoice_type/${facturaId}`,
  },
};
